function tableRows(col){const rows=model()[col].filter(r=>JSON.stringify(r).toLowerCase().includes(filter.toLowerCase()));return rows.map(r=>'<tr data-action="inspect" data-id="'+esc(r.id)+'">'+columns[col].map(([k],i)=>{let value=r[k];if(k==='status')value=badge(value);else if(isReference(col,k))value=esc(ref(value));else if(k==='rackU')value=r.rackU?'U'+r.rackU+'–'+(r.rackU+r.height-1):'Unplaced';else if(Array.isArray(value))value=esc(value.map(x=>find(x)?ref(x):x).join(', ')||'—');else value=esc(value===0?0:value||'—');return '<td'+(!i?' class="cell-main"':'')+'>'+(!i?'<button data-action="inspect" data-id="'+esc(r.id)+'" class="quiet small" style="border:0;padding:0;text-align:left">'+value+'</button>':value)+(!i&&r.notes?'<div class="cell-sub">'+esc(truncate(r.notes,90))+'</div>':'')+'</td>';}).join('')+'</tr>').join('')||'<tr><td colspan="'+columns[col].length+'" class="muted">No matching records.</td></tr>';}
function renderDecisions(){return header('Decisions, with their reasoning.','Keep alternatives visible, link affected items, and record the chosen option and rationale when the team reaches an outcome.','<button data-action="edit" data-col="decisions" class="primary small">+ Add decision</button>')+'<div class="cards">'+model().decisions.map(d=>'<article class="panel decision-card" data-action="inspect" data-id="'+esc(d.id)+'">'+badge(d.status)+'<h2>'+esc(d.title)+'</h2><p>'+esc(truncate(d.context,180))+'</p>'+d.options.map(o=>'<span class="option-chip '+(d.selectedOptionId===o.id?'chosen':'')+'">'+(d.selectedOptionId===o.id?'✓ ':'')+esc(o.label)+'</span>').join('')+'<div class="card-footer"><span>'+esc(d.owner||'Owner needed')+'</span><span>'+esc(d.due||'No target date')+'</span></div></article>').join('')+'</div>'+(!model().decisions.length?empty('Capture the next design question','Add alternatives before selecting an outcome.','Add decision','decisions'):'');}
function renderEvidence(){return header('Evidence & reference library','Attach rack photos, existing drawings, and supporting PDFs. Files are embedded in project exports and remain linked to their design records.','<button data-action="edit" data-col="evidence" class="primary small">+ Attach file</button>')+'<div class="notice">Attachments travel inside Project JSON and Portable HTML. Browser storage has a size limit; export a project file after adding important evidence.</div><div class="cards">'+model().evidence.map(e=>'<article class="panel evidence-card"><div class="evidence-preview" data-action="inspect" data-id="'+esc(e.id)+'">'+(e.mime.startsWith('image/')?'<img src="'+esc(e.data)+'" alt="'+esc(e.caption||e.name)+'">':'<span class="mono">PDF / REFERENCE DOCUMENT</span>')+'</div><div class="panel-body"><h3>'+esc(e.name)+'</h3><p>'+esc(e.caption||'No caption')+'</p><div class="card-footer"><span>'+esc(e.relatedId?ref(e.relatedId):'Project reference')+'</span><button data-action="download-evidence" data-id="'+esc(e.id)+'" class="small">Download</button></div></div></article>').join('')+'</div>'+(!model().evidence.length?empty('Bring the existing design into the room','Attach Rack Studio exports, network drawings, or equipment photos.','Attach file','evidence'):'');}
