function renderRevisions(){if(!bundle.revisions.some(r=>r.id===selectedRevision))selectedRevision=bundle.revisions[0]?.id||'';const rev=bundle.revisions.find(r=>r.id===selectedRevision),changes=rev?DS.diff(rev.model,model()):[];return header('A history you can walk through.','Capture named design baselines, compare them with the current draft, and restore an earlier design while preserving a safety revision.','<button data-action="capture" class="primary small">↶ Capture revision</button>')+'<div class="notice">Revisions are local project snapshots with entered author labels. Export Project JSON or Portable HTML to carry this history to another machine.</div><div class="history-grid"><div>'+bundle.revisions.map(r=>'<article class="revision-card '+(r.id===selectedRevision?'active':'')+'" data-action="select-revision" data-id="'+esc(r.id)+'"><div class="eyebrow">'+esc(date(r.time))+'</div><h3>'+esc(r.name)+'</h3><p>'+esc(r.author)+'</p></article>').join('')+'</div><div class="stack"><section class="panel"><div class="panel-head"><div><div class="eyebrow">Selected baseline → current draft</div><h2>'+changes.length+' changes since '+esc(rev?.name||'baseline')+'</h2></div>'+(rev?'<button data-action="restore" data-id="'+esc(rev.id)+'" class="small">Restore this revision</button>':'')+'</div>'+(changes.map(d=>diffHTML(d,rev.model,model())).join('')||empty('The draft matches this baseline','New changes will appear here.'))+'</section><section class="panel"><div class="panel-head"><h2>Recent editing activity</h2></div>'+bundle.activity.slice(0,15).map(a=>'<div class="diff"><b>'+esc(a.text)+'</b><p style="margin-left:0">'+esc(date(a.time))+' · '+esc(a.author)+'</p></div>').join('')+'</section></div></div>';}
